package com.bank.batch;

import java.util.*;
import java.util.logging.*;

public class ResultDemo {
    private static final Logger log = Logger.getLogger("Batch");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> raw = List.of("100", "oops", "250", "bad");
        BatchService service = new BatchService();

        Map<Boolean, List<Result<Integer>>> outcome = service.process(raw);
        log.info(() -> "successes: " + outcome.get(true).stream().map(Result::value).toList());
        log.warning(() -> "failures : " + outcome.get(false).stream().map(Result::error).toList());
    }
}

