// Either-like holder: success value OR error message
record Result<T>(T value, String error) {
    static <T> Result<T> ok(T v) { return new Result<>(v, null); }
    static <T> Result<T> fail(String e) { return new Result<>(null, e); }
    boolean isSuccess() { return error == null; }
}

// ─── Would be in service/BatchService.java ───
class BatchService {
    // map each element to a Result (never throws), then partition
    Map<Boolean, List<Result<Integer>>> process(List<String> raw) {
        return raw.stream()
            .map(this::parseSafe)                              // String → Result<Integer>
            .collect(java.util.stream.Collectors.partitioningBy(Result::isSuccess));
    }

    private Result<Integer> parseSafe(String s) {
        try {
            return Result.ok(Integer.parseInt(s));            // success
        } catch (NumberFormatException e) {
            return Result.fail("bad: " + s);                  // failure captured, not thrown
        }
    }
}
